import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Relazione binaria di un insieme su sé stesso","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/j_teoria-degli-insiemi/jc/jcb.md","filePath":"lezioni/j_teoria-degli-insiemi/jc/jcb.md"}`),a={name:`lezioni/j_teoria-degli-insiemi/jc/jcb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="relazione-binaria-di-un-insieme-su-se-stesso" tabindex="-1">Relazione binaria di un insieme su sé stesso <a class="header-anchor" href="#relazione-binaria-di-un-insieme-su-se-stesso" aria-label="Permalink to “Relazione binaria di un insieme su sé stesso”">​</a></h1><p>Particolarmente interessante è parlare di relazioni quando i due insiemi <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> coincidono; in tal caso si parla di relazione binaria di un insieme su sé stesso oppure semplicemente <strong>relazione binaria su un insieme</strong>.</p><blockquote><p>D&#39;ora in avanti considereremo solo questo tipo di relazione, e, nelle prossime pagine ne considereremo i vari tipi elementari, cosa che ci permetterà di &quot;partizionare&quot; od anche &quot;ordinare&quot; un insieme.</p></blockquote><p>Vediamone qualche esempio:</p><p>Considero l&#39;insieme degli abitanti dell&#39;Italia e considero la relazione [&quot;abita nella stessa città&quot;]{.text-red} per ogni coppia di cittadini italiani è possibile dire se la relazione è vera o falsa</p><hr><p>Considero gli alunni di una scuola e considero la relazione [&quot;è nato nello stesso anno di&quot;]{.text-red} per ogni coppia di alunni è possibile dire se la relazione è vera o falsa</p><hr><p>Considero gli alunni di una scuola e considero la relazione [&quot;è più alto di&quot;]{.text-red} per ogni coppia di alunni è possibile dire se il primo è più alto del secondo</p><hr><p>Considero l&#39;insieme dei primi <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> numeri naturali e considero la relazione [&quot;è maggiore od uguale di&quot;]{.text-red} per ogni coppia di numeri puoi dire se il primo è maggiore od uguale rispetto al secondo</p><hr><p>Come vedi è molto facile fare una relazione: basta confrontare fra loro le caratteristiche di alcuni elementi dell&#39;insieme di partenza.</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};